def filter_out_low_numbers(numbers: List[float]) -> List[float]:
    """ This function will remove numbers from a given list, that are lower than
    the middle value of the list.
    >>> filter_out_low_numbers([3.0, 1.0, 2.0, 4.0])
    [3.0, 2.0, 4.0]
    >>> filter_out_low_numbers([2.5, 3.0, 1.5, 3.1])
    [3.0, 3.1]
    """
    middle = sorted(numbers)[len(numbers) // 2]
    for i in range(len(numbers)):
        if numbers[i] < middle:
            numbers.pop(i)
    return numbers


