def filter_by_substrings(strings: List[str], substrings: List[str]) -> List[str]:
    """ Filter an input list of strings based on a list of substrings,
    filter only strings that contain all given substrings.
    """
    return [s for s in strings if all(substring in s for substring in substrings)]


def contains_substrings(strings: List[str], substrings: List[str]) -> List[str]:
    """Filter an input list of strings based on a list of substrings,
    keep only strings that contain each substring at least once.
    """
    result = []
    for s in strings:
        contain_all = True
        for substring in substrings:
            if substring not in s:
                contain_all = False
                break
        if contain_all:
            result.append(s)
    return result


